"""Amount helpers shared by the ledger."""
from decimal import Decimal, ROUND_HALF_UP


def parse_amount(text):
    """'1,234.50' -> Decimal('1234.50'). Thousands commas allowed; anything else not a number raises ValueError."""
    cleaned = text.strip().replace(",", "")
    try:
        return Decimal(cleaned)
    except Exception as e:
        raise ValueError(f"not an amount: {text!r}") from e


def format_amount(value):
    """Decimal -> '1234.50': two decimals, half up."""
    return str(Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

