from collections import defaultdict
from decimal import Decimal

from ledger.util import parse_amount


def monthly_totals(rows):
    totals = defaultdict(Decimal)
    for row in rows:
        totals[row["date"][:7]] += parse_amount(row["amount"])
    return dict(totals)

