"""Monthly totals as CSV text for a spreadsheet."""
import abc
import csv
import io

from ledger.util import format_amount


class Exporter(abc.ABC):
    """Base for every export format."""

    @abc.abstractmethod
    def header(self):
        ...

    @abc.abstractmethod
    def render(self, rows):
        ...


class CsvExporter(Exporter):
    def header(self):
        return ["month", "total"]

    def render(self, rows):
        out = io.StringIO()
        w = csv.writer(out)
        w.writerow(self.header())
        w.writerows(rows)
        return out.getvalue()


EXPORTERS = {"csv": CsvExporter}


def get_exporter(name="csv"):
    return EXPORTERS[name]()


def export_csv(totals):
    rows = [[month, format_amount(totals[month])] for month in sorted(totals)]
    return get_exporter("csv").render(rows)

