from ledger.util import format_amount


def _quote(field):
    field = str(field)
    if any(c in field for c in ',"\r\n'):
        return '"' + field.replace('"', '""') + '"'
    return field


def _line(fields):
    return ",".join(_quote(f) for f in fields) + "\r\n"


def export_csv(totals):
    text = _line(["month", "total"])
    for month in sorted(totals):
        text += _line([month, format_amount(totals[month])])
    return text

